-- ------------------------------------------------------------
-- 1) Dimensiones
-- ------------------------------------------------------------
CREATE TABLE TiempoHorario (
    idTiempo        NUMBER(19)      NOT NULL,
    fecHora         TIMESTAMP       NOT NULL,         -- siempre en UTC
    fecha           DATE            NOT NULL,
    hora            NUMBER(2)       NOT NULL,
    diaSemana       NUMBER(1)       NOT NULL,
    mes             NUMBER(2)       NOT NULL,
    year            NUMBER(4)       NOT NULL,
    indFinSemana    NUMBER(1)       DEFAULT 0 NOT NULL,
    indFestivo      NUMBER(1)       DEFAULT 0 NOT NULL, -- CAMBIO: antes "insFestivo" (el NF1 dice indFestivo)
    CONSTRAINT pk_tiempo_horario PRIMARY KEY (idTiempo),
    CONSTRAINT uk_tiempo_fec_hora UNIQUE (fecHora),
    CONSTRAINT chk_hora CHECK (hora BETWEEN 0 AND 23),
    CONSTRAINT chk_dia_semana CHECK (diaSemana BETWEEN 1 AND 7),
    CONSTRAINT chk_mes CHECK (mes BETWEEN 1 AND 12),
    CONSTRAINT chk_fin_semana CHECK (indFinSemana IN (0, 1)),
    CONSTRAINT chk_ind_festivo CHECK (indFestivo IN (0, 1))
);

CREATE TABLE FestivosBOE (
    idFestivo       NUMBER(19) GENERATED BY DEFAULT AS IDENTITY,
    fecha           DATE            NOT NULL,
    nombreFestivo   VARCHAR2(150)   NOT NULL,
    ambito          VARCHAR2(50),                      -- Nacional / Autonomico
    codCCAA         VARCHAR2(10),
    CONSTRAINT pk_festivos_boe PRIMARY KEY (idFestivo)
);

CREATE TABLE ComunidadAutonoma (
    idCCAA                NUMBER(10) GENERATED BY DEFAULT AS IDENTITY,
    codIne                VARCHAR2(10)    NOT NULL,
    nombreCCAA            VARCHAR2(100)   NOT NULL,
    latitudCentroide      NUMBER(10, 6),
    longitudCentroide     NUMBER(10, 6),
    CONSTRAINT pk_comunidad_autonoma PRIMARY KEY (idCCAA),
    CONSTRAINT uk_ccaa_cod_ine UNIQUE (codIne)
);

CREATE TABLE Roles (
    idRol       NUMBER(10) GENERATED BY DEFAULT AS IDENTITY,
    rol         VARCHAR2(50)    NOT NULL,
    descripcion CLOB,
    CONSTRAINT pk_roles PRIMARY KEY (idRol),
    CONSTRAINT uk_roles_nombre UNIQUE (rol)
);

CREATE TABLE ModelosML (
    idModelo                NUMBER(10) GENERATED BY DEFAULT AS IDENTITY, -- CAMBIO: antes "idMdelo" (typo)
    nombreAlgoritmo         VARCHAR2(100)   NOT NULL,
    version                 VARCHAR2(20)    NOT NULL,
    rutaFicheroArtifact     VARCHAR2(255),
    metricaMAE              NUMBER(12, 4),
    metricaRMSE             NUMBER(12, 4),
    metricaMAPE             NUMBER(12, 4),                             -- NUEVO: el NF1 pide MAE, RMSE y MAPE
    indActivo               NUMBER(1)       DEFAULT 1 NOT NULL,
    fecEntrenamiento        TIMESTAMP       DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT pk_modelos_ml PRIMARY KEY (idModelo),
    CONSTRAINT uk_modelo_alg_version UNIQUE (nombreAlgoritmo, version),
    CONSTRAINT chk_modelo_activo CHECK (indActivo IN (0, 1))
);

CREATE TABLE RedTransporte (
    idRed               NUMBER(10) GENERATED BY DEFAULT AS IDENTITY,
    idCCAA              NUMBER(10)      NOT NULL,
    year                NUMBER(4)       NOT NULL,
    kmLineas400kv       NUMBER(10, 2),
    kmLineas220kv       NUMBER(10, 2),
    numPosiciones       NUMBER(10),
    CONSTRAINT pk_red_transporte PRIMARY KEY (idRed),
    CONSTRAINT uk_red_ccaa_year UNIQUE (idCCAA, year),
    CONSTRAINT fk_red_transporte_ccaa FOREIGN KEY (idCCAA)
        REFERENCES ComunidadAutonoma(idCCAA)
);

CREATE TABLE Usuarios (
    idUsuario       NUMBER(10) GENERATED BY DEFAULT AS IDENTITY,
    CIF             VARCHAR2(20)    NOT NULL,          -- CAMBIO: ahora NOT NULL (el registro es por CIF)
    nombre          VARCHAR2(100)   NOT NULL,
    email           VARCHAR2(150)   NOT NULL,
    passwd_hash     VARCHAR2(255)   NOT NULL,          -- BCrypt
    idRol           NUMBER(10)      NOT NULL,
    activo          NUMBER(1)       DEFAULT 1 NOT NULL,
    fecCreacion     TIMESTAMP       DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT pk_usuarios PRIMARY KEY (idUsuario),
    CONSTRAINT uk_usuarios_email UNIQUE (email),
    CONSTRAINT fk_usuarios_rol FOREIGN KEY (idRol)
        REFERENCES Roles(idRol),
    CONSTRAINT chk_usuario_activo CHECK (activo IN (0, 1))
);

-- ------------------------------------------------------------
-- 2) Hechos: mercado, meteorologia y demanda
-- ------------------------------------------------------------
CREATE TABLE PreciosMercadoOmie (
    idPrecio            NUMBER(19) GENERATED BY DEFAULT AS IDENTITY,
    idTiempo            NUMBER(19)      NOT NULL,
    precioMarginalES    NUMBER(10, 4),
    precioMarginalPT    NUMBER(10, 4),
    tipMercado          VARCHAR2(50),                    -- diario / intradiario
    CONSTRAINT pk_precios_omie PRIMARY KEY (idPrecio),
    CONSTRAINT uk_precios_tiempo_mercado UNIQUE (idTiempo, tipMercado),
    CONSTRAINT fk_precios_tiempo FOREIGN KEY (idTiempo)
        REFERENCES TiempoHorario(idTiempo)
);

CREATE TABLE OfertaDemandaOmie (
    idCurva                 NUMBER(19) GENERATED BY DEFAULT AS IDENTITY,
    idTiempo                NUMBER(19)      NOT NULL,
    pais                    VARCHAR2(10)    NOT NULL,
    potenciaCompraVenta     NUMBER(12, 4),
    precioCompraVenta       NUMBER(12, 4),
    tipOferta               VARCHAR2(50),
    tipologiaOferta         VARCHAR2(50),
    CONSTRAINT pk_oferta_demanda_omie PRIMARY KEY (idCurva),
    CONSTRAINT fk_oferta_tiempo FOREIGN KEY (idTiempo)
        REFERENCES TiempoHorario(idTiempo)
);

CREATE TABLE Meteorologia (
    idMeteo                  NUMBER(19) GENERATED BY DEFAULT AS IDENTITY,
    idTiempo                 NUMBER(19)      NOT NULL,
    idCCAA                   NUMBER(10)      NOT NULL,
    temperatura_2m           NUMBER(5, 2),
    temperaturaAparente      NUMBER(5, 2),
    viento_10m               NUMBER(5, 2),
    viento_80m               NUMBER(5, 2),
    viento_120m              NUMBER(5, 2),
    viento_180m              NUMBER(5, 2),
    viento_dir_10m           NUMBER(5, 2),     -- NUEVO: Dirección del viento a 10m (Open-Meteo)
    viento_dir_80m           NUMBER(5, 2),     -- NUEVO: Dirección del viento a 80m (Open-Meteo)
    viento_dir_120m          NUMBER(5, 2),     -- NUEVO: Dirección del viento a 120m (Open-Meteo)
    viento_dir_180m          NUMBER(5, 2),     -- NUEVO: Dirección del viento a 180m (Open-Meteo)
    radiacion_directa        NUMBER(8, 2),
    shortwave_radiation      NUMBER(8, 2),     -- NUEVO: Radiación de onda corta (Open-Meteo)
    global_tilted_irradiance NUMBER(8, 2),     -- NUEVO: Irradiancia global inclinada (Open-Meteo)
    cobertura_nubes          NUMBER(3),
    humedad_relativa         NUMBER(3),
    CONSTRAINT pk_meteorologia PRIMARY KEY (idMeteo),
    CONSTRAINT uk_meteo_tiempo_ccaa UNIQUE (idTiempo, idCCAA),
    CONSTRAINT fk_meteo_tiempo FOREIGN KEY (idTiempo)
        REFERENCES TiempoHorario(idTiempo),
    CONSTRAINT fk_meteo_ccaa FOREIGN KEY (idCCAA)
        REFERENCES ComunidadAutonoma(idCCAA)
);

CREATE TABLE DemandaGeneracionREE (
    idDemanda                 NUMBER(19) GENERATED BY DEFAULT AS IDENTITY,
    idTiempo                  NUMBER(19)      NOT NULL,
    idCCAA                    NUMBER(10)      NOT NULL,      -- usar la fila '00' (Nacional) si el dato es agregado
    demandaRealMW             NUMBER(12, 4),
    demandaPrevistaREEMW      NUMBER(12, 4),
    demandaProgramadaMW       NUMBER(12, 4),                 -- NUEVO: Demanda programada (REE)
    demandaProgramadaTotalMW  NUMBER(12, 4),                 -- NUEVO: Demanda programada total (REE)
    genEolicaMW               NUMBER(12, 4),
    genSolarMW                NUMBER(12, 4),
    genHidraulicaMW           NUMBER(12, 4),
    genNuclearMW              NUMBER(12, 4),
    genCicloCombinadoMW       NUMBER(12, 4),
    CONSTRAINT pk_demanda_generacion_ree PRIMARY KEY (idDemanda),
    CONSTRAINT uk_demanda_tiempo_ccaa UNIQUE (idTiempo, idCCAA),
    CONSTRAINT fk_demanda_tiempo FOREIGN KEY (idTiempo)
        REFERENCES TiempoHorario(idTiempo),
    CONSTRAINT fk_demanda_ccaa FOREIGN KEY (idCCAA)
        REFERENCES ComunidadAutonoma(idCCAA)
);

-- ------------------------------------------------------------
-- 3) Resultados del modelo, impacto economico y alertas
-- ------------------------------------------------------------
CREATE TABLE PrediccionesDemanda (
    idPrediccion        NUMBER(19) GENERATED BY DEFAULT AS IDENTITY,
    idTiempo            NUMBER(19)      NOT NULL,
    idModelo            NUMBER(10)      NOT NULL,
    idCCAA              NUMBER(10)      NOT NULL,      -- NUEVO: el dashboard filtra por region
    demandaPredichaMW   NUMBER(12, 4),                 -- CAMBIO: antes "...MWH" (el NF1 y la API usan MW)
    demandaBaselineMW   NUMBER(12, 4),                 -- NUEVO: baseline de persistencia horaria (CU-04)
    fecha               TIMESTAMP DEFAULT CURRENT_TIMESTAMP, -- momento de ejecucion del pipeline
    CONSTRAINT pk_predicciones_demanda PRIMARY KEY (idPrediccion),
    CONSTRAINT fk_pred_tiempo FOREIGN KEY (idTiempo)
        REFERENCES TiempoHorario(idTiempo),
    CONSTRAINT fk_pred_modelo FOREIGN KEY (idModelo)
        REFERENCES ModelosML(idModelo),
    CONSTRAINT fk_pred_ccaa FOREIGN KEY (idCCAA)
        REFERENCES ComunidadAutonoma(idCCAA)
);

CREATE TABLE ImpactoDesviaciones (
    idImpacto               NUMBER(19) GENERATED BY DEFAULT AS IDENTITY,
    idTiempo                NUMBER(19)      NOT NULL,
    idPrediccion            NUMBER(19),                -- NUEVO: enlaza cada coste con su prediccion (NF1 apdo. 7.2)
    idCCAA                  NUMBER(10)      NOT NULL,  -- NUEVO
    demandaRealMW           NUMBER(12, 4),             -- CAMBIO: MWH -> MW
    demandaPredichaMW       NUMBER(12, 4),
    desviacionMW            NUMBER(12, 4),
    precioOmieEurMWH        NUMBER(10, 4),             -- el precio SI es EUR/MWh
    costeDesvioEstimadoEur  NUMBER(14, 4),
    nivelAlerta             VARCHAR2(50),
    CONSTRAINT pk_impacto_desviaciones PRIMARY KEY (idImpacto),
    CONSTRAINT chk_impacto_nivel CHECK (nivelAlerta IN ('NORMAL', 'PRECAUCION', 'CRITICO')),
    CONSTRAINT fk_impacto_tiempo FOREIGN KEY (idTiempo)
        REFERENCES TiempoHorario(idTiempo),
    CONSTRAINT fk_impacto_prediccion FOREIGN KEY (idPrediccion)
        REFERENCES PrediccionesDemanda(idPrediccion),
    CONSTRAINT fk_impacto_ccaa FOREIGN KEY (idCCAA)
        REFERENCES ComunidadAutonoma(idCCAA)
);

CREATE TABLE Alertas_operativas (
    idAlerta                NUMBER(19) GENERATED BY DEFAULT AS IDENTITY,
    idTiempo                NUMBER(19)      NOT NULL,
    nivelAlerta             VARCHAR2(50)    NOT NULL,
    costePotencialEur       NUMBER(14, 4),
    mensaje                 CLOB,
    estado                  VARCHAR2(50)    NOT NULL,  -- p. ej. ACTIVA / RESUELTA
    idUsuarioResponsable    NUMBER(10),
    CONSTRAINT pk_alertas_operativas PRIMARY KEY (idAlerta),
    CONSTRAINT chk_alerta_nivel CHECK (nivelAlerta IN ('NORMAL', 'PRECAUCION', 'CRITICO')),
    CONSTRAINT fk_alertas_tiempo FOREIGN KEY (idTiempo)
        REFERENCES TiempoHorario(idTiempo),
    CONSTRAINT fk_alertas_usuario FOREIGN KEY (idUsuarioResponsable)
        REFERENCES Usuarios(idUsuario)
);

-- ------------------------------------------------------------
-- 4) Indices (Oracle NO crea indices automaticos sobre las FK)
-- ------------------------------------------------------------
CREATE INDEX ix_usuarios_cif        ON Usuarios(CIF);
CREATE INDEX ix_usuarios_rol        ON Usuarios(idRol);
CREATE INDEX ix_festivos_fecha      ON FestivosBOE(fecha);
CREATE INDEX ix_tiempo_fecha        ON TiempoHorario(fecha);
CREATE INDEX ix_oferta_tiempo       ON OfertaDemandaOmie(idTiempo);
CREATE INDEX ix_meteo_ccaa          ON Meteorologia(idCCAA);
CREATE INDEX ix_demanda_ccaa        ON DemandaGeneracionREE(idCCAA);
CREATE INDEX ix_pred_tiempo_ccaa    ON PrediccionesDemanda(idTiempo, idCCAA);
CREATE INDEX ix_pred_modelo         ON PrediccionesDemanda(idModelo);
CREATE INDEX ix_impacto_tiempo_ccaa ON ImpactoDesviaciones(idTiempo, idCCAA);
CREATE INDEX ix_impacto_prediccion  ON ImpactoDesviaciones(idPrediccion);
CREATE INDEX ix_alertas_tiempo      ON Alertas_operativas(idTiempo);
CREATE INDEX ix_alertas_usuario     ON Alertas_operativas(idUsuarioResponsable);

